using System.Text.Json;
using VisualQa.Core;
namespace VisualQa.Figma;
public sealed class FigmaSpecParser { public JsonElement Parse(string json) { using var doc=JsonDocument.Parse(json); return doc.RootElement.Clone(); } }
public sealed class FigmaNormalizer { public DesignComponentSpec Normalize(JsonElement root,string? componentName=null) { var node=root.TryGetProperty("document",out var document)?document:root; var elements=new List<DesignElementSpec>(); Walk(node,elements); var box=Bounds(node); return new(){Name=componentName??Get(node,"name")??"FigmaComponent",Width=box?.Width,Height=box?.Height,Elements=elements}; }
 void Walk(JsonElement node,List<DesignElementSpec> output) { if(node.ValueKind!=JsonValueKind.Object)return; var id=Get(node,"id"); if(id is not null) output.Add(new(){Id=QaId(id,Get(node,"name")),Name=Get(node,"name")??id,Type=Get(node,"type"),Bounds=Bounds(node),Text=Get(node,"characters"),FontFamily=Nested(node,"style","fontFamily"),FontSize=Number(node,"style","fontSize"),FontWeight=Nested(node,"style","fontWeight"),LineHeight=Number(node,"style","lineHeightPx"),LetterSpacing=Number(node,"style","letterSpacing"),ForegroundColor=Paint(node,"fills"),BackgroundColor=Paint(node,"backgrounds")}); if(node.TryGetProperty("children",out var children))foreach(var child in children.EnumerateArray())Walk(child,output); }
 static string QaId(string id,string? name)=> (name??id).Trim().ToLowerInvariant().Replace(' ','-'); static string? Get(JsonElement e,string name)=>e.TryGetProperty(name,out var x)&&x.ValueKind==JsonValueKind.String?x.GetString():null; static string? Nested(JsonElement e,string a,string b)=>e.TryGetProperty(a,out var x)?Get(x,b):null; static double? Number(JsonElement e,string a,string b)=>e.TryGetProperty(a,out var x)&&x.TryGetProperty(b,out var y)&&y.TryGetDouble(out var n)?n:null; static RectSpec? Bounds(JsonElement e)=>e.TryGetProperty("absoluteBoundingBox",out var b)&&b.TryGetProperty("x",out var x)&&b.TryGetProperty("y",out var y)&&b.TryGetProperty("width",out var w)&&b.TryGetProperty("height",out var h)?new(x.GetDouble(),y.GetDouble(),w.GetDouble(),h.GetDouble()):null; static string? Paint(JsonElement e,string name)=>e.TryGetProperty(name,out var p)&&p.ValueKind==JsonValueKind.Array&&p.GetArrayLength()>0&&p[0].TryGetProperty("color",out var c)?$"#{(int)(c.GetProperty("r").GetDouble()*255):X2}{(int)(c.GetProperty("g").GetDouble()*255):X2}{(int)(c.GetProperty("b").GetDouble()*255):X2}":null; }
